import pathlib,json,re,hashlib,datetime
P=pathlib.Path('experiments/2026-10-20-farmana-reserve-review'); L=pathlib.Path('data/raw/2026-10-20-farmana-reserve-review')
rows=json.loads((L/'identity-checks.json').read_text()); log=json.loads((L/'ACCESS-LOG.json').read_text())
for r in rows:
 for c in r['coordinates']:
  t=(L/f'page-{c["pdf_page"]:04d}.txt').read_text(); c['printed_page_matches']=bool(re.search(r'-\s*'+str(c['pdf_page']-14)+r'\s*-',t)); c['captions']=[x.strip() for x in t.splitlines() if x.strip().startswith(('Figure','Table'))]
(L/'identity-checks.json').write_text(json.dumps(rows,indent=2))
log['access'] += [{'path':'data/normalized/lipi_observed_faces.jsonl','operation':'hash and parse for identity fields of families 154 and 155; an initial whole metadata mapping exposed incidental sign-count/text-length field values to reviewer only; these were not used or relayed. No prediction, score or model file accessed.'},{'path':'data/raw/2026-10-20-fresh-test-collection/pages','operation':'complete-page pixel inspection of bounded plates 231,232,387 and caption-recovery pages 283,322; no sign decoding'}]
log['completed_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat(); log['incidental_reserved_content_exposure']=True
(L/'ACCESS-LOG.json').write_text(json.dumps(log,indent=2))
result={'authors':['GPT-6.1-Sol / Codex desktop / reserve_identity_review'],'verification_tier':'reviewed','hash_checks':91,'hash_failures':0,'candidate_identifier_rows':36,'rows_with_valid_pdf_coordinates_and_identifier_text':sum(all(c['identifier_present'] and c['printed_page_matches'] for c in r['coordinates']) for r in rows),'rows_with_existing_hashed_image_witnesses':36,'pixel_scope_pdf_pages':[231,232,283,322,387],'all_pages_pixel_reviewed':False,'conditional_absence_claims_supported':15,'absence_assumptions':['Pinned Farmana site identification and recorded loci are correct.','Different explicit loci distinguish objects; no unrecorded relocation or duplicate registration.','Corpus family 154 block 2D3 conflicts with excavation-ID-derived 2D9; both differ from the 15 candidate contexts.','Corpus family 155 ID5 is interpreted as 1D5; alias normalization remains provisional.'],'uncertain_alias_rows_retained':16,'known_match_rows_retained':5,'source_total_conflict':{'reported':29,'candidate_identifiers':30,'unresolved_pair':['FRN2011-P859','FRN2011-P860'],'physical_object_count':'unresolved'},'metadata_gaps':{'pottery_individual_dimensions_unavailable':30,'pottery_museum_accessions_unavailable':30,'pottery_registration_crosswalk_unavailable':30,'complete_physical_face_coverage_unknown':36,'source_table_dimensions_available_but_not_structured_in_register':6},'corrections_proposed':['Clarify family 154 block 2D3 versus excavation-ID-derived 2D9; preserve both.','Structure available Table 7.2/7.3 dimensions and context for S-1 through S-6 in a new derivative.','Retain P859/P860 separately as candidate identifiers with unresolved relation.'],'frozen_test_eligible':0,'new_seal_test_eligibility_implied':False,'custody':'reviewer exposed; parent/model-builder reserve preserved procedurally; technical isolation absent','raw_details':'local-only identity-checks.json and access log; no source images, signs or motif descriptions in safe report'}
(P/'independent-verification.json').write_text(json.dumps(result,indent=2))
files=[]
for p in sorted(L.iterdir()):
 if p.is_file(): files.append({'path':p.as_posix(),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
(P/'local-review-hashes.json').write_text(json.dumps({'files':files},indent=2))
print(json.dumps({k:result[k] for k in ['hash_checks','hash_failures','rows_with_valid_pdf_coordinates_and_identifier_text','conditional_absence_claims_supported','frozen_test_eligible']}))
